{
  "name": "Modbus TCP服务器",
  "name_en": "Modbus TCP Server",
  "manufacturer": "",
  "description": "这是一个基于网络的 Modbus TCP 服务器组件，不对应特定厂商的实体仪器。它通常用于实验室自动化系统中提供或模拟 Modbus 通信接口，使上位机、PLC 或测试程序能够与实验设备进行寄存器级数据交换与联调。",
  "description_en": "This is a network-based Modbus TCP server component rather than a specific physical instrument from a known manufacturer. It is typically used in laboratory automation to provide or simulate a Modbus communication interface so that host software, PLCs, or test systems can exchange register-level data with laboratory equipment during integration and testing.",
  "tag_hints": [
    "Modbus TCP",
    "industrial communication",
    "lab automation integration",
    "device simulation",
    "register data exchange",
    "network protocol testing"
  ],
  "actions": [
    {
      "action_name": "auto-start",
      "description": "启动 Modbus TCP 服务器。",
      "description_en": "Start the Modbus TCP server."
    },
    {
      "action_name": "auto-stop",
      "description": "停止 Modbus TCP 服务器。",
      "description_en": "Stop the Modbus TCP server."
    },
    {
      "action_name": "auto-is_run",
      "description": "获取服务器是否正在运行。",
      "description_en": "Get whether the server is currently running."
    },
    {
      "action_name": "auto-srv_info",
      "description": "获取服务器信息。",
      "description_en": "Get server information."
    },
    {
      "action_name": "auto-new_request",
      "description": "创建或处理新的 Modbus 请求。",
      "description_en": "Create or handle a new Modbus request."
    },
    {
      "action_name": "auto-set_response_mbap",
      "description": "设置响应报文的 MBAP 头信息。",
      "description_en": "Set the MBAP header for the response frame."
    },
    {
      "action_name": "auto-raw",
      "description": "获取原始 Modbus 报文数据。",
      "description_en": "Get the raw Modbus frame data."
    },
    {
      "action_name": "auto-func_code",
      "description": "获取 Modbus 功能码。",
      "description_en": "Get the Modbus function code."
    },
    {
      "action_name": "auto-except_code",
      "description": "获取 Modbus 异常码。",
      "description_en": "Get the Modbus exception code."
    },
    {
      "action_name": "auto-is_except",
      "description": "获取报文是否为异常响应。",
      "description_en": "Get whether the frame is an exception response."
    },
    {
      "action_name": "auto-is_valid",
      "description": "获取报文是否有效。",
      "description_en": "Get whether the frame is valid."
    },
    {
      "action_name": "auto-clear",
      "description": "清除当前报文或缓存内容。",
      "description_en": "Clear the current frame or buffered content."
    },
    {
      "action_name": "auto-build_except",
      "description": "构建 Modbus 异常响应报文。",
      "description_en": "Build a Modbus exception response frame."
    },
    {
      "action_name": "auto-add_pack",
      "description": "向报文中添加数据包内容。",
      "description_en": "Add packet content to the message frame."
    },
    {
      "action_name": "auto-unpack",
      "description": "解析并解包 Modbus 报文。",
      "description_en": "Parse and unpack a Modbus frame."
    },
    {
      "action_name": "auto-server_running",
      "description": "获取服务器运行状态。",
      "description_en": "Get the server running state."
    },
    {
      "action_name": "auto-handle",
      "description": "处理收到的 Modbus 请求。",
      "description_en": "Handle an incoming Modbus request."
    }
  ]
}

